import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch111Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final String GRUNT="bw8_en_125",TRIAD="bw9_en_102",BALL="bw9_en_105",MON="bw8_en_049",STAGE="bw8_en_003",ENERGY="bw8_en_127",TRAINER="bw8_en_118";
    static final List<String> IDS=List.of(GRUNT,TRIAD,BALL),PLASMA=List.of(MON,STAGE,ENERGY,TRAINER,GRUNT);
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static void settle(ServerMatch m){NonPokemonBatch103Test.settle(m);}
    static ServerMatch game(String id){
        var kinds=List.of("basic","basic",MON,STAGE,"energy",ENERGY,TRAINER,GRUNT,"trainer","trainer");var definitions=new ArrayList<CardDefinition>();var pokemon=new HashMap<String,PokemonProfile>();var trainers=Map.of("trainer",profile(id),GRUNT,profile(GRUNT),TRAINER,profile(TRAINER));
        for(String key:new LinkedHashSet<>(kinds)){boolean mon=Set.of("basic",MON,STAGE).contains(key),energy=Set.of("energy",ENERGY).contains(key);definitions.add(new CardDefinition(key,key.equals("basic")?"Team Plasma decoy":key,mon?CardCategory.POKEMON:energy?CardCategory.ENERGY:CardCategory.TRAINER,mon||energy?TrainerCategory.NONE:trainers.get(key).category(),"H",Set.of("international"),mon&&!key.equals(STAGE),key.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));if(mon)pokemon.put(key,new PokemonProfile(1000,0,key.equals(STAGE)?"basic":null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(300,false)),List.of(),EnergyType.COLORLESS));}
        var combat=new CombatCatalog(pokemon,Map.of("energy",EnergyType.GRASS),trainers,Map.of(ENERGY,NonPokemonBatch2Test.DATA.energyProfile(ENERGY).orElseThrow()));
        for(int seed=0;seed<1000;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(definitions),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,22);m.drawCardsByEffect(A,B,22);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->new HashSet<>(kinds).stream().allMatch(k->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(k)))&&List.of(MON,STAGE).stream().allMatch(k->m.privateView(p).deck().stream().anyMatch(c->c.definitionId().equals(k)))))return m;}throw new AssertionError("Plasma selection fixture unavailable");
    }
    static ServerMatch aiGame(String id){var m=game(id);if(id.equals(TRIAD))for(UUID p:List.of(A,B))m.discardHandCardsByEffect(A,p,List.of(hand(m,p,ENERGY).instanceId()));return m;}
    static void turn(ServerMatch m,UUID p){if(p.equals(B))m.endTurn(A);}
    static void play(ServerMatch m,UUID p){m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);}
    public static void main(String[] args){metadata();search();recover();grunt();empty();schema();ai();System.out.println("NonPokemonBatch111Test passed: audited printed Team Plasma identity including all known raw printings, no name inference; Ball Basic/evolved only with fail-to-find and reveal, Triad all card categories with own discard authority, Grunt mandatory other-card discard and draw-four including empty/short deck, both owners and four AI difficulties");}
    static void metadata(){var effects=profile(BALL).effectProgram().triggers().getFirst().effects();var ids=Set.of(effects.getFirst().arguments().get("definition_ids").split("\\|"));check(ids.containsAll(PLASMA)&&ids.contains("bw8_en_134")&&ids.contains("bwalt_en_110")&&!ids.contains("bw10_en_089")&&!ids.contains("basic"),"Plasma identity lost a printing or guessed from name");}
    static void search(){for(UUID p:List.of(A,B))for(String selected:List.of(MON,STAGE,"skip","none")){
        var m=game(BALL);turn(m,p);if(selected.equals("none")){var deck=PairedTrainerPlayTest.zone(m,p,"deck");var removed=deck.stream().filter(c->Set.of(MON,STAGE).contains(c.definitionId())).toList();deck.removeAll(removed);PairedTrainerPlayTest.zone(m,p,"hand").addAll(removed);}int before=m.privateView(p).hand().size();play(m,p);if(selected.equals("none")){settle(m);check(m.privateView(p).hand().size()==before-1,"Empty Plasma search changed hand");continue;}var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->Set.of(MON,STAGE).contains(c.definitionId())),"Ball admitted ordinary Pokemon or non-Pokemon Plasma card");GeneratedRuleBatch8Test.reject(()->m.effectCardPrompt(other(p)));var take=Set.of("skip","none").contains(selected)?List.<CardInstance>of():List.of(q.candidates().stream().filter(c->c.definitionId().equals(selected)).findFirst().orElseThrow());m.submitEffectCards(p,q.resolutionId(),q.step(),take.stream().map(CardInstance::instanceId).toList());settle(m);check(m.privateView(p).hand().containsAll(take)&&m.privateView(p).hand().size()==before-1+take.size(),"Ball moved wrong number of cards");
    }}
    static void recover(){for(UUID p:List.of(A,B))for(String kind:PLASMA){var m=game(TRIAD);turn(m,p);var card=hand(m,p,kind);var decoy=hand(m,p,"basic");m.discardHandCardsByEffect(p,p,List.of(card.instanceId(),decoy.instanceId()));var foreign=hand(m,other(p),ENERGY);m.discardHandCardsByEffect(p,other(p),List.of(foreign.instanceId()));play(m,p);var q=m.effectCardPrompt(p);check(q.candidates().equals(List.of(card)),"Triad ignored affiliation, category or ownership");GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(foreign.instanceId())));m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(card.instanceId()));settle(m);check(m.privateView(p).hand().contains(card)&&m.privateView(p).discard().contains(decoy)&&m.privateView(other(p)).discard().contains(foreign),"Triad moved the wrong card");}}
    static void grunt(){for(UUID p:List.of(A,B))for(String kind:PLASMA)for(int deckSize:List.of(0,2,10)){
        var m=game(GRUNT);turn(m,p);var card=hand(m,p,kind);var deck=PairedTrainerPlayTest.zone(m,p,"deck");if(deck.size()>deckSize){var excess=new ArrayList<>(deck.subList(deckSize,deck.size()));deck.removeAll(excess);PairedTrainerPlayTest.zone(m,p,"discard").addAll(excess);}int before=m.privateView(p).hand().size();play(m,p);var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->PLASMA.contains(c.definitionId()))&&!q.candidates().contains(hand(m,p,"basic")),"Grunt cost ignored printed affiliation");GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of()));m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(card.instanceId()));settle(m);check(m.privateView(p).discard().contains(card)&&m.privateView(p).hand().size()==before-2+Math.min(4,deckSize),"Grunt did not discard exactly one then draw up to four");check(m.phase()!=MatchPhase.FINISHED,"Effect draw incorrectly caused deck-out");
    }}
    static void empty(){for(UUID p:List.of(A,B))for(String id:List.of(GRUNT,TRIAD)){var m=game(id);turn(m,p);var trainer=hand(m,p,id.equals(GRUNT)?GRUNT:"trainer");if(id.equals(GRUNT)){var discard=m.privateView(p).hand().stream().filter(c->!c.equals(trainer)&&PLASMA.contains(c.definitionId())).map(CardInstance::instanceId).toList();m.discardHandCardsByEffect(p,p,discard);}check(!m.canPlayTrainer(p,trainer.instanceId(),null),"Trainer played without mandatory Plasma target / used itself as cost");var before=m.privateView(p);GeneratedRuleBatch8Test.reject(()->m.playTrainer(p,trainer.instanceId(),null));check(m.privateView(p).equals(before),"Rejected Plasma Trainer consumed hand or Supporter");}}
    static void schema(){var cost=profile(GRUNT).effectProgram().triggers().getFirst().effects().getFirst();check(ActivationCostRules.handCost(cost)==1,"Grunt must retain mandatory payment");for(String key:List.of("definition_ids","amount","minimum")){var args=new HashMap<>(cost.arguments());if(key.equals("definition_ids"))args.remove(key);else args.put(key,"2");GeneratedRuleBatch8Test.reject(()->ActivationCostRules.handCost(new EffectDefinition(cost.type(),cost.target(),args,List.of(),List.of())));}}
    static void ai(){for(String id:IDS)for(var level:AiDifficulty.values()){var m=aiGame(id);play(m,A);var session=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(session,level);AiCardOperationTest.finish(session,level);check(m.phase()==MatchPhase.FINISHED,"Plasma AI stalled: "+id);}}
}
